def seed_members(apps, schema_editor):
    Mshiriki = apps.get_model('kanda', 'Mshiriki')
    for name, phone, family in MEMBERS:
        if phone:
            mshiriki, created = Mshiriki.objects.get_or_create(
                simu=phone,
                defaults={'jina': name, 'familia': family, 'jukumu': 'MSHIRIKI', 'is_active': True}
            )
            if not created:
                mshiriki.jina = name
                mshiriki.is_active = True
                mshiriki.save()
        else:
            # Bila simu
            if not Mshiriki.objects.filter(jina=name).exists():
                Mshiriki.objects.create(jina=name, simu='', familia=family, jukumu='MSHIRIKI', is_active=True)

